<script setup>
import {ref,computed} from 'vue';import {Head,Link,useForm} from '@inertiajs/vue3';import axios from 'axios';import CoveragePicker from '../Components/CoveragePicker.vue';import Errors from '../Components/Errors.vue';import {art,message,date} from '../art';
const props=defineProps({catalog:Object,decks:Array});
const form=useForm({title:'My Memory Maki deck',subjects:[...props.catalog.subjects],topics:[],topic_scope:'all',difficulty:'All',range_start:1,range_end:20,selected_ids:[]});
const preview=ref(null),error=ref(''),busy=ref(false),fingerprint=ref('');
const topics=computed(()=>props.catalog.topics.filter(t=>form.subjects.includes(t.subject)));
const key=()=>JSON.stringify([form.subjects,form.topics,form.difficulty,form.range_start,form.range_end]);
const stale=computed(()=>fingerprint.value!==key());
async function find(){busy.value=true;error.value='';form.topics=form.topics.filter(t=>form.subjects.includes(t.split('\u001f')[0]));try{const r=await axios.post('/flashcards/preview',form.data());preview.value=r.data;form.selected_ids=r.data.questions.map(q=>q.id);fingerprint.value=key()}catch(e){error.value=message(e)}finally{busy.value=false}}
</script><template><Head title="Memory Maki"/><div class="page-title"><div><p class="eyebrow">Meet Memo Maki</p><h1>Memory Maki</h1><p>Build your deck, answer for immediate feedback, and rate your familiarity from 1 to 5.</p></div><img class="portrait large" :src="art.memo" alt="Memo Maki holding flashcards"></div>
<form class="panel" @submit.prevent="find"><label>Deck name<input v-model="form.title" required maxlength="150"></label><CoveragePicker :form="form" :catalog="catalog"/><div class="form-grid"><label>Difficulty<select v-model="form.difficulty"><option>All</option><option>Easy</option><option>Average</option><option>Difficult</option></select></label><label>Range: first question<input v-model.number="form.range_start" type="number" min="1" required></label><label>Range: last question<input v-model.number="form.range_end" type="number" min="1" required></label></div><p class="muted">The range uses the ordered questions matching your filters, starting at 1. Include up to 500 questions per deck, then select the individual items below.</p><button class="primary" :disabled="busy||!form.subjects.length||(form.topic_scope=== 'custom'&&!form.topics.length)">Preview question range</button><p v-if="error" class="notice error" role="alert">{{error}}</p></form>
<section v-if="preview" class="panel"><h2>Questions in your deck</h2><p>{{preview.total}} questions match the filters. {{preview.questions.length}} are in this range. {{form.selected_ids.length}} selected.</p><p v-if="stale" class="notice">Filters changed. Preview the range again before starting.</p><div class="row"><button @click="form.selected_ids=preview.questions.map(q=>q.id)">Select all</button><button @click="form.selected_ids=[]">Clear selection</button></div><div class="deck-question-list"><label v-for="q in preview.questions" :key="q.id" class="check"><input type="checkbox" v-model="form.selected_ids" :value="q.id"><span><strong>{{q.id}} · {{q.subject}}</strong><small>{{q.topic}}</small>{{q.stem}}</span></label></div><Errors :errors="form.errors"/><button class="primary" :disabled="stale||!form.selected_ids.length||form.processing" @click="form.post('/flashcards/decks')">Start this deck</button></section>
<section class="panel"><h2>Your saved decks</h2><p v-if="!decks.length">Your decks and familiarity counts will stay here between study sessions.</p><div v-for="d in decks" :key="d.id" class="row spaced"><div><strong>{{d.title}}</strong><p>{{d.items_count}} questions · {{d.reviews}} ratings · {{date(d.updated_at)}}</p></div><Link :href="'/flashcards/decks/'+d.id" class="button">Resume deck</Link></div></section>
<p class="notice">Within a deck, rating-1 questions have six times the draw weight of rating-5 questions. Unrated cards also receive high priority. There are no day-based waiting periods.</p>
</template>
